import {checks,reviewIsCurrent} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

export function decisionCardMarkup(s,{uncertain=false}={}){
 const current=!uncertain&&!!s.review&&reviewIsCurrent(s),matched=s.evidenceAvailable!==false&&checks(s).every(x=>x.ok),verified=proofIsCurrent(s)&&!uncertain;
 const label=verified?'Verified outcome':s.paymentHold?'Payment review required':uncertain?'Refresh evidence first':s.phase==='rehearsed'?'Your decision':s.phase==='approved'?'Approved correction':s.writes?'Verification required':current&&matched?'Recommendation ready':'Investigation needed';
 const recommendation=verified?'Technical checks agree. Ask the customer to confirm access on their device.':s.paymentHold?'Review the changed payment before considering access.':uncertain?'Refresh the payment and course records before any decision.':s.writes?'Reread payment, access, and the protected lesson. Do not repeat the grant.':s.phase==='rehearsed'?'Compare the exact preview below. Approve only if the customer, course, and payment still match.':current&&matched?'A narrow access correction can be previewed. No change is authorized yet.':'Keep access unchanged while evidence is gathered or discrepancies are resolved.';
 const evidence=[['Payment',s.capture?.status==='COMPLETED'&&s.evidenceAvailable!==false],['Exact purchase',matched],['Review',current],['Lesson proof',verified]];
 const exact=checks(s),failed=exact.filter(item=>!item.ok),open=current?(s.review.objections||[]).filter(item=>item.status==='open'):[];
 const blockers=[...(uncertain?['The displayed case may be out of date.']:[]),...(s.evidenceAvailable===false?['Payment evidence is unavailable.']:[]),...failed.map(item=>item.label+' does not match.'),...open.map(item=>item.question)];
 if(!current&&!verified)blockers.push('A current specialist review is required.');
 const sources=current?[...new Set((s.analysis?.findings||[]).flatMap(item=>item.sources||[]))]:[];
 const basis=exact.slice(0,5).map(item=>`<li class="${item.ok&&s.evidenceAvailable!==false?'pass':'hold'}"><span>${item.ok&&s.evidenceAvailable!==false?'✓':'!'}</span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></li>`).join('');
 return `<section class="merchant-decision" aria-label="Merchant decision brief"><span class="eyebrow">WHY THIS ACTION?</span><h2>${esc(label)}</h2><p>${esc(recommendation)}</p><div class="decision-evidence">${evidence.map(([name,ok])=>`<span class="${ok?'pass':'pending'}"><b>${ok?'✓':'·'}</b> ${esc(name)}</span>`).join('')}</div><details class="decision-basis"><summary>See the case facts behind this decision</summary><ul>${basis}</ul><p>${current?`Saved review cites: ${esc(sources.length?sources.join(', '):'the purchase and access records')}. Open each specialist to inspect the frozen source record.`:'Run a fresh investigation before relying on a specialist recommendation.'}</p></details><div class="decision-blockers"><strong>What could stop the repair</strong>${blockers.length?`<ul>${blockers.slice(0,4).map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p>No open mismatch is shown in this case. Fresh checks and exact approval are still required.</p>'}</div><div class="decision-change"><strong>What changes</strong><p>${s.writes?'One access grant is recorded. No second grant is planned.':s.rehearsal?'Only the purchased course entitlement shown in the preview. Payment and account ownership do not change.':'Nothing changes until a current preview is approved.'}</p></div><small>${current?'These facts support a recommendation, not permission to change access.':'A current specialist review is required before a recommendation can support a correction.'}</small></section>`;
}
